16	package org.springframework.samples.petclinic.util;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	
22	/**
23	 * Shared helpers for an owner's duplicate-detection identity: the derived identity key and the
24	 * Soundex reduction of a surname it is built from. Kept in one place so the create endpoint (which
25	 * computes the key for duplicate/soft-match detection) and the mapper (which exposes it on the
26	 * response) agree exactly.
27	 */
28	public final class OwnerIdentity {
29	
30	    private OwnerIdentity() {
31	    }
32	
33	    /**
34	     * The owner's derived duplicate-detection identity key: the lower-case SHA-256 hex digest over
35	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}. A {@code null} telephone or
36	     * email contributes the empty string, the email is lower-cased so the comparison is
37	     * case-insensitive, and the last name is reduced to its Soundex code so near-identical surnames
38	     * collide.
39	     */
40	    public static String identityKey(String normalizedTelephone, String email, String lastName) {
41	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
42	        String emailKey = email == null ? "" : email.toLowerCase();
43	        return sha256Hex(telephone + "|" + emailKey + "|" + soundex(lastName));
44	    }
45	
46	    /**
47	     * The full lower-case SHA-256 hex digest of the UTF-8 bytes of {@code input}.
48	     */
49	    public static String sha256Hex(String input) {
50	        try {
51	            byte[] digest = MessageDigest.getInstance("SHA-256")
52	                .digest(input.getBytes(StandardCharsets.UTF_8));
53	            StringBuilder sb = new StringBuilder(digest.length * 2);
54	            for (byte b : digest) {
55	                sb.append(String.format("%02x", b));
56	            }
57	            return sb.toString();
58	        }
59	        catch (NoSuchAlgorithmException e) {
60	            throw new IllegalStateException(e);
61	        }
62	    }
63	
64	    /**
65	     * The American Soundex code of {@code name}: the upper-cased first letter followed by up to three
66	     * digits derived from the remaining letters (b,f,p,v -> 1; c,g,j,k,q,s,x,z -> 2; d,t -> 3; l -> 4;
67	     * m,n -> 5; r -> 6), where adjacent letters sharing a code (directly, or separated only by 'h' or
68	     * 'w') collapse to a single digit and vowels act as separators, right-padded with zeros to length
69	     * four. A {@code null} or letter-free input yields the empty string.
70	     */
71	    public static String soundex(String name) {
72	        if (name == null) {
73	            return "";
74	        }
75	        StringBuilder letters = new StringBuilder();
76	        for (char c : name.toUpperCase().toCharArray()) {
77	            if (c >= 'A' && c <= 'Z') {
78	                letters.append(c);
79	            }
80	        }
81	        if (letters.length() == 0) {
82	            return "";
83	        }
84	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
85	        char previous = soundexCode(letters.charAt(0));
86	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
87	            char letter = letters.charAt(i);
88	            char digit = soundexCode(letter);
89	            if (digit != '0' && digit != previous) {
90	                code.append(digit);
91	            }
92	            if (letter != 'H' && letter != 'W') {
93	                previous = digit;
94	            }
95	        }
96	        while (code.length() < 4) {
97	            code.append('0');
98	        }
99	        return code.toString();
100	    }
101	
102	    private static char soundexCode(char c) {
103	        return switch (c) {
104	            case 'B', 'F', 'P', 'V' -> '1';
105	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
106	            case 'D', 'T' -> '3';
107	            case 'L' -> '4';
108	            case 'M', 'N' -> '5';
109	            case 'R' -> '6';
110	            default -> '0';
111	        };
112	    }
