3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.time.LocalDate;
13	import java.time.Period;
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
24	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
25	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
28	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
29	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
30	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
31	    @Mapping(target = "membershipPoints", expression = "java(formatMembershipPoints(owner))")
32	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
33	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
34	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
35	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
36	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
37	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
38	    @Mapping(target = "ownerSegment", expression = "java(formatOwnerSegment(owner))")
39	    @Mapping(target = "bulkSignupWarning", ignore = true)
40	    @Mapping(target = "capacityWarning", ignore = true)
41	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
42	    OwnerDto toOwnerDto(Owner owner);
43	
44	    /**
45	     * Derives an owner's age band from the birth date, computed against the registration date
46	     * (falling back to the current date when the registration date is absent): {@code MINOR} when
47	     * under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older. Returns
48	     * {@code null} when no birth date is present, so the field is omitted from the response.
49	     */
50	    default OwnerDto.AgeBandEnum formatAgeBand(Owner owner) {
51	        if (owner == null || owner.getBirthDate() == null) {
52	            return null;
53	        }
54	        LocalDate asOf = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
55	        int age = Period.between(owner.getBirthDate(), asOf).getYears();
56	        if (age < 18) {
57	            return OwnerDto.AgeBandEnum.MINOR;
58	        }
59	        if (age < 65) {
60	            return OwnerDto.AgeBandEnum.ADULT;
61	        }
62	        return OwnerDto.AgeBandEnum.SENIOR;
63	    }
64	
65	    /**
66	     * Derives an owner's segment formatted {@code '<TIER>_<AREA>'}. TIER is {@code PREMIUM} when
67	     * the membership level is 3 or more, otherwise {@code STANDARD}. AREA is {@code METRO} when the
68	     * locality is a known region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise {@code REGIONAL}.
69	     * Returns {@code null} when the owner is {@code null}.
70	     */
71	    default OwnerDto.OwnerSegmentEnum formatOwnerSegment(Owner owner) {
72	        if (owner == null) {
73	            return null;
74	        }
75	        boolean premium = formatMembershipLevel(owner) >= 3;
76	        String locality = formatLocality(owner);
77	        boolean metro = "NSW".equals(locality) || "VIC".equals(locality) || "QLD".equals(locality);
78	        if (premium) {
79	            return metro ? OwnerDto.OwnerSegmentEnum.PREMIUM_METRO : OwnerDto.OwnerSegmentEnum.PREMIUM_REGIONAL;
80	        }
81	        return metro ? OwnerDto.OwnerSegmentEnum.STANDARD_METRO : OwnerDto.OwnerSegmentEnum.STANDARD_REGIONAL;
82	    }
83	
84	    /**
85	     * Derives an owner's duplicate-detection identity key as the lower-case SHA-256 hex digest over
86	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} from the stored (already
87	     * E.164-normalized) telephone, lower-cased email and the Soundex code of the last name. A
88	     * {@code null} telephone or email contributes the empty string in its position.
89	     */
90	    default String formatIdentityKey(Owner owner) {
91	        if (owner == null) {
92	            return null;
93	        }
94	        return org.springframework.samples.petclinic.util.OwnerIdentity.identityKey(
95	            owner.getTelephone(), owner.getEmail(), owner.getLastName());
96	    }
97	
98	    /**
99	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
100	     * (non-null and non-blank), otherwise {@code PHONE}.
101	     */
102	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
103	        if (owner == null) {
104	            return null;
105	        }
106	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
107	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
108	    }
109	
110	    /**
111	     * Derives an owner's locality (region) from the customer-code identity: it is the {@code REGION}
112	     * segment of the {@code '<REGION>-<HASH8>'} customer code (the part before the first {@code '-'}).
113	     * When the customer code is absent it falls back to resolving the region directly, preferring the
114	     * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and then the fixed city-to-region
115	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), yielding
116	     * {@code "UNKNOWN"} when neither resolves.
117	     */
118	    default String formatLocality(Owner owner) {
119	        if (owner == null) {
120	            return null;
121	        }
122	        String code = owner.getCustomerCode();
123	        if (code != null) {
124	            int dash = code.indexOf('-');
125	            if (dash > 0) {
126	                return code.substring(0, dash);
127	            }
128	        }
129	        String fromPostcode = regionForPostcode(owner.getPostcode());
130	        if (fromPostcode != null) {
131	            return fromPostcode;
132	        }
133	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
134	            case "Sydney" -> "NSW";
135	            case "Melbourne" -> "VIC";
136	            case "Brisbane" -> "QLD";
137	            default -> "UNKNOWN";
138	        };
139	    }
140	
141	    /**
142	     * Derives an owner's IANA timezone from the locality (region) via the fixed region-to-timezone
143	     * table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
144	     * {@code QLD -> Australia/Brisbane}. Returns {@code null} when the region is not one of these,
145	     * so the field is omitted from the response.
146	     */
147	    default String formatTimezone(Owner owner) {
148	        if (owner == null) {
149	            return null;
150	        }
151	        return switch (formatLocality(owner)) {
152	            case "NSW" -> "Australia/Sydney";
153	            case "VIC" -> "Australia/Melbourne";
154	            case "QLD" -> "Australia/Brisbane";
155	            default -> null;
156	        };
157	    }
158	
159	    /**
160	     * Resolves a region from a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099,
161	     * QLD 4000-4099). Returns {@code null} when the postcode is absent, not exactly 4 digits, or in
162	     * no known range, signalling that the caller should fall back to the city-to-region table.
163	     */
164	    private String regionForPostcode(String postcode) {
165	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
166	            return null;
167	        }
168	        int value = Integer.parseInt(postcode);
169	        if (value >= 2000 && value <= 2099) {
170	            return "NSW";
171	        }
172	        if (value >= 3000 && value <= 3099) {
173	            return "VIC";
174	        }
175	        if (value >= 4000 && value <= 4099) {
176	            return "QLD";
177	        }
178	        return null;
179	    }
180	
181	    /**
182	     * Computes an owner's membership points, starting at 0: plus 2 when an email is present, plus 1
183	     * when the owner's namesake count is 0, plus 2 for a household of 3 or more, plus 3 when the
184	     * owner's tenure exceeds 365 days.
185	     */
186	    default Integer formatMembershipPoints(Owner owner) {
187	        if (owner == null) {
188	            return null;
189	        }
190	        int points = 0;
191	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
192	        if (hasEmail) {
193	            points += 2;
194	        }
195	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
196	        if (unique) {
197	            points += 1;
198	        }
199	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
200	        if (largeHousehold) {
201	            points += 2;
202	        }
203	        boolean tenured = owner.getRegistrationDate() != null
204	            && fiscalYearStart(LocalDate.now()) - fiscalYearStart(owner.getRegistrationDate()) >= 1;
205	        if (tenured) {
206	            points += 3;
207	        }
208	        return points;
209	    }
210	
211	    /**
212	     * Derives an owner's membership level, a number from 1 to 4, from the owner's membership points:
213	     * 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
214	     */
215	    default Integer formatMembershipLevel(Owner owner) {
216	        if (owner == null) {
217	            return null;
218	        }
219	        int points = formatMembershipPoints(owner);
220	        if (points <= 1) {
221	            return 1;
222	        }
223	        if (points <= 3) {
224	            return 2;
225	        }
226	        if (points <= 5) {
227	            return 3;
228	        }
229	        return 4;
230	    }
231	
232	    /**
233	     * Computes an owner's check digit: a single Luhn check digit (0-9) over the digits contained in the
234	     * customer code. Returns {@code null} when the customer code is absent.
235	     */
236	    default Integer formatCheckDigit(Owner owner) {
237	        if (owner == null || owner.getCustomerCode() == null) {
238	            return null;
239	        }
240	        String code = owner.getCustomerCode();
241	        int sum = 0;
242	        boolean dbl = true;
243	        for (int i = code.length() - 1; i >= 0; i--) {
244	            char c = code.charAt(i);
245	            if (c < '0' || c > '9') {
246	                continue;
247	            }
248	            int d = c - '0';
249	            if (dbl) {
250	                d *= 2;
251	                if (d > 9) {
252	                    d -= 9;
253	                }
254	            }
255	            sum += d;
256	            dbl = !dbl;
257	        }
258	        return (10 - (sum % 10)) % 10;
259	    }
260	
261	    /**
262	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
263	     * digits of the fiscal year (starting 1 July) of the business-day-adjusted registration date
264	     * (e.g. {@code "NSW-1A2B3C4D-M26"}). Returns {@code null} when the customer code or registration
265	     * date is absent.
266	     */
267	    default String formatMembershipNumber(Owner owner) {
268	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
269	            return null;
270	        }
271	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYearStart(owner.getRegistrationDate()) % 100);
272	    }
273	
274	    /**
275	     * Formats an owner's fiscal year as {@code 'FY<YY>'}, where YY is the last two digits of the
276	     * starting calendar year of the fiscal year (starting 1 July) that contains the owner's
277	     * business-day-adjusted registration date (e.g. 5 August 2026 yields {@code "FY26"} and 3 March
278	     * 2026 yields {@code "FY25"}). Returns {@code null} when the registration date is absent.
279	     */
280	    default String formatFiscalYear(Owner owner) {
281	        if (owner == null || owner.getRegistrationDate() == null) {
282	            return null;
283	        }
284	        return String.format("FY%02d", fiscalYearStart(owner.getRegistrationDate()) % 100);
285	    }
286	
287	    /**
288	     * Returns the starting calendar year of the fiscal year (which starts on 1 July) that contains
289	     * the given date: the date's own year when it falls on or after 1 July, otherwise the previous
290	     * year.
291	     */
292	    private int fiscalYearStart(LocalDate date) {
293	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
294	    }
295	
296	    /**
297	     * Formats an owner's stored E.164 telephone for humans as the country code, a space, and the
298	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
299	     * The raw {@code telephone} value stays in E.164 form. Returns the stored value unchanged when it
300	     * is {@code null} or not a well-formed E.164 string (a {@code '+'} followed by digits).
301	     */
302	    default String formatTelephoneDisplay(Owner owner) {
303	        if (owner == null) {
304	            return null;
305	        }
306	        String telephone = owner.getTelephone();
307	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
308	            return telephone;
309	        }
310	        String digits = telephone.substring(1);
311	        int countryCodeLength = countryCodeLength(digits);
312	        String countryCode = digits.substring(0, countryCodeLength);
313	        String national = digits.substring(countryCodeLength);
314	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
315	        for (int i = 0; i < national.length(); i += 3) {
316	            grouped.append(' ').append(national, i, Math.min(i + 3, national.length()));
317	        }
318	        return grouped.toString();
319	    }
320	
321	    /**
322	     * Determines the length of the country-code segment of an E.164 number's digits (its digits
323	     * without the leading {@code '+'}): 1 for the NANP ({@code '+1'}) and 2 otherwise (e.g. Australia's
324	     * {@code '+61'}), mirroring the country codes the application normalises to.
325	     */
326	    private int countryCodeLength(String digits) {
327	        return digits.startsWith("1") ? 1 : 2;
328	    }
329	
330	    /**
331	     * Formats an owner's canonical self link as {@code "/api/owners/" + id} from the stored id.
332	     * Returns {@code null} when the owner or its id is absent, so the field is omitted from the
333	     * response.
334	     */
335	    default String formatSelfLink(Owner owner) {
336	        if (owner == null || owner.getId() == null) {
337	            return null;
338	        }
339	        return "/api/owners/" + owner.getId();
340	    }
341	
342	    /**
343	     * Formats an owner's display name as {@code "LastName, FirstName"} from the stored names.
344	     */
345	    default String formatDisplayName(Owner owner) {
346	        if (owner == null) {
347	            return null;
348	        }
349	        return owner.getLastName() + ", " + owner.getFirstName();
350	    }
351	
352	    /**
353	     * Formats an owner's salutation as the title and last name separated by a single space
354	     * (e.g. {@code "DR Franklin"}) when a title is present, or just the last name when no title
355	     * is given (null or blank). Returns {@code null} when the owner is {@code null}.
356	     */
357	    default String formatSalutation(Owner owner) {
358	        if (owner == null) {
359	            return null;
360	        }
361	        String title = owner.getTitle();
362	        if (title == null || title.isBlank()) {
363	            return owner.getLastName();
364	        }
365	        return title + " " + owner.getLastName();
366	    }
367	
368	    /**
369	     * Formats an owner's initials as the upper-cased first letters of the first and last
370	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
371	     */
372	    default String formatInitials(Owner owner) {
373	        if (owner == null) {
374	            return null;
375	        }
376	        return initial(owner.getFirstName()) + initial(owner.getLastName());
377	    }
378	
379	    private String initial(String name) {
380	        if (name == null || name.isEmpty()) {
381	            return "";
382	        }
383	        return Character.toUpperCase(name.charAt(0)) + ".";
384	    }
385	
386	    Owner toOwner(OwnerDto ownerDto);
387	
388	    @Mapping(target = "id", ignore = true)
389	    @Mapping(target = "pets", ignore = true)
390	    Owner toOwner(OwnerFieldsDto ownerDto);
391	
392	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
393	
394	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
395	
396	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
397	        OwnerPageDto ownerPageDto = new OwnerPageDto();
398	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
399	        ownerPageDto.setPage(ownerPage.getNumber());
400	        ownerPageDto.setSize(ownerPage.getSize());
401	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
402	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
403	        return ownerPageDto;
404	    }
405	}
