245	    /**
246	     * Derive the stable, shared household identifier for owners in the same household: the first 12
247	     * lower-case hex characters of the SHA-256 digest over {@code '<normalizedLastName>|<postcode>'},
248	     * so every owner with the same last name and postcode resolves to the same value regardless of
249	     * the order in which they were created.
250	     */
251	    private static String householdId(String lastNameKey, String postcode) {
252	        return hashHex(lastNameKey + "|" + (postcode == null ? "" : postcode), 12, false);
253	    }
254	
255	    /**
256	     * Count how many owners belong to the given owner's household (owners sharing its normalized last
257	     * name and postcode). An owner without a postcode has no household peers and counts as a household
258	     * of one.
259	     */
260	    private int householdSize(Owner owner) {
261	        if (owner.getPostcode() == null) {
262	            return 1;
263	        }
264	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
265	        return (int) this.clinicService.findAllOwners().stream()
266	            .filter(existing -> existing.getPostcode() != null
267	                && householdId.equals(
268	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
269	            .count();
270	    }
271	
272	    /**
273	     * The existing, non-deleted owners that belong to {@code owner}'s household (sharing its
274	     * normalized last name and postcode), excluding {@code owner} itself. An owner without a
275	     * postcode has no household peers, so this is empty.
276	     */
277	    private List<Owner> otherHouseholdMembers(Owner owner) {
278	        if (owner.getPostcode() == null) {
279	            return List.of();
280	        }
281	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
282	        return this.clinicService.findAllOwners().stream()
283	            .filter(existing -> !existing.isDeleted())
284	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
285	            .filter(existing -> existing.getPostcode() != null
286	                && householdId.equals(
287	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
288	            .toList();
289	    }
290	
291	    /**
292	     * The owner's membership level after applying the household ceiling: the natural level derived
293	     * from the owner's membership points, capped at one above the current maximum membership level
294	     * among the owner's existing household members. With no existing household member no cap applies.
295	     * Assumes the owner's household size has already been populated.
296	     */
297	    private Integer cappedMembershipLevel(Owner owner) {
298	        Integer natural = ownerMapper.formatMembershipLevel(owner);
299	        if (natural == null) {
300	            return null;
301	        }
302	        List<Owner> members = otherHouseholdMembers(owner);
303	        if (members.isEmpty()) {
304	            return natural;
305	        }
306	        int maxMemberLevel = 0;
307	        for (Owner member : members) {
308	            member.setHouseholdSize(householdSize(member));
309	            Integer memberLevel = ownerMapper.formatMembershipLevel(member);
310	            if (memberLevel != null) {
311	                maxMemberLevel = Math.max(maxMemberLevel, memberLevel);
312	            }
313	        }
314	        return Math.min(natural, maxMemberLevel + 1);
315	    }
