375	    /**
376	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
377	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
378	     * fixed city-to-region table, else {@code "UNKNOWN"}.
379	     */
380	    private static String region(String postcode, String city) {
381	        String fromPostcode = regionForPostcode(postcode);
382	        return fromPostcode != null ? fromPostcode : regionForCity(city);
383	    }
384	
385	    /**
386	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
387	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
388	     */
389	    private static String regionForPostcode(String postcode) {
390	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
391	            return null;
392	        }
393	        int value = Integer.parseInt(postcode);
394	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
395	            int[] range = entry.getValue();
396	            if (value >= range[0] && value <= range[1]) {
397	                return entry.getKey();
398	            }
399	        }
400	        return null;
401	    }
