546	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
547	    @Override
548	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
549	        String idempotencyKey = currentIdempotencyKey();
550	        if (idempotencyKey != null) {
551	            Integer existingId = this.idempotentCreations.get(idempotencyKey);
552	            if (existingId != null) {
553	                Owner existing = this.clinicService.findOwnerById(existingId);
554	                if (existing != null) {
555	                    existing.setHouseholdSize(householdSize(existing));
556	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
557	                    existingDto.setMembershipLevel(cappedMembershipLevel(existing));
558	                    existingDto.setBulkSignupWarning(existing.getRegistrationDate() != null
559	                        && ownersCreatedOn(existing.getRegistrationDate()) > 80);
560	                    existingDto.setCapacityWarning(capacityWarning(existing.getCity()));
561	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
562	                }
563	            }
564	        }
565	        String telephone = toE164(ownerFieldsDto.getTelephone());
566	        if (telephone == null) {
567	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
568	        }
569	        String email = ownerFieldsDto.getEmail();
570	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
571	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
572	        }
573	        if (isDisposableEmailDomain(email)) {
574	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
575	        }
576	        // Structured address is preferred when supplied (a non-blank 'addressLine1'); otherwise the
577	        // flat 'address' input is used for backward compatibility. Normalization applies to whichever
578	        // fields are supplied, and the composed 'address' is the normalized addressLine1 with the
579	        // normalized addressLine2 appended after a single space when present.
580	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
581	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
582	        boolean structuredAddress = !addressLine1.isEmpty();
583	        String address;
584	        if (structuredAddress) {
585	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
586	        } else {
587	            address = normaliseAddress(ownerFieldsDto.getAddress());
588	        }
589	        if (address.isEmpty()) {
590	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
591	        }
592	        String postcode = ownerFieldsDto.getPostcode();
593	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
594	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
595	        }
596	        if (ownerFieldsDto.getRegistrationDate() != null
597	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
598	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
599	        }
600	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
601	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
602	        LocalDate registrationDate = toBusinessDay(effectiveDate);
603	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
604	            .map(Owner::getRegistrationDate)
605	            .filter(existing -> existing != null)
606	            .map(OwnerRestControllerV1::toBusinessDay)
607	            .filter(registrationDate::equals)
608	            .count();
609	        if (ownersCreatedThatDay >= 100) {
610	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
611	        }
612	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
613	        long ownersInCity = this.clinicService.findAllOwners().stream()
614	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
615	            .count();
616	        if (ownersInCity >= 50) {
617	            return new ResponseEntity<>(HttpStatus.CONFLICT);
618	        }
619	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
620	        // The household is deterministically keyed on (normalized last name, postcode): every owner
621	        // with a postcode belongs to the household identified by this computed id, and owners sharing
622	        // a last name and postcode share it automatically. A new owner may join an existing household;
623	        // the household ceiling below (rather than a hard rejection) governs its membership level.
624	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
625	        // Duplicate detection is the single identity key (normalized telephone, lower-cased email and
626	        // Soundex of the last name). A candidate whose key collides with an existing, non-deleted
627	        // owner is a hard duplicate (409); the household id no longer participates in this decision.
628	        String identityKey = OwnerIdentity.identityKey(telephone, email, ownerFieldsDto.getLastName());
629	        boolean identityInUse = this.clinicService.findAllOwners().stream()
630	            .filter(existing -> !existing.isDeleted())
631	            .anyMatch(existing -> OwnerIdentity.identityKey(toE164(existing.getTelephone()),
632	                existing.getEmail(), existing.getLastName()).equals(identityKey));
633	        if (identityInUse) {
634	            return new ResponseEntity<>(HttpStatus.CONFLICT);
635	        }
636	        // Soft match: an existing, non-deleted owner sharing this owner's postcode and last-name
637	        // Soundex but with a different identity key (e.g. a different telephone) is not a hard
638	        // duplicate, but the new owner is flagged as a possible duplicate of it.
639	        String lastNameSoundex = OwnerIdentity.soundex(ownerFieldsDto.getLastName());
640	        Integer possibleDuplicateOf = (postcode == null) ? null
641	            : this.clinicService.findAllOwners().stream()
642	                .filter(existing -> !existing.isDeleted())
643	                .filter(existing -> postcode.equals(existing.getPostcode()))
644	                .filter(existing -> lastNameSoundex.equals(OwnerIdentity.soundex(existing.getLastName())))
645	                .filter(existing -> !OwnerIdentity.identityKey(toE164(existing.getTelephone()),
646	                    existing.getEmail(), existing.getLastName()).equals(identityKey))
647	                .map(Owner::getId)
648	                .findFirst()
649	                .orElse(null);
650	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
651	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
652	            .filter(existing ->
653	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
654	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
655	            .count();
656	        HttpHeaders headers = new HttpHeaders();
657	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
658	        owner.setNamesakeCount(namesakeCount);
659	        owner.setAddress(address);
660	        if (structuredAddress) {
661	            owner.setAddressLine1(addressLine1);
662	            owner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
663	        } else {
664	            owner.setAddressLine1(null);
665	            owner.setAddressLine2(null);
666	        }
667	        owner.setTelephone(telephone);
668	        owner.setEmail(email == null ? null : email.toLowerCase());
669	        owner.setRegistrationDate(registrationDate);
670	        owner.setCustomerCode(deduplicateCustomerCode(nextCustomerCode(
671	            region(postcode, owner.getCity()), telephone, owner.getLastName())));
672	        owner.setHouseholdId(householdId);
673	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
674	        this.clinicService.saveOwner(owner);
675	        if (idempotencyKey != null) {
676	            this.idempotentCreations.put(idempotencyKey, owner.getId());
677	        }
678	        owner.setHouseholdSize(householdSize(owner));
679	        Integer membershipLevel = cappedMembershipLevel(owner);
680	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
681	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
682	            membershipLevel, ownerMapper.formatMembershipNumber(owner));
683	        // Immutable structured event carrying the owner's current primary identifier (the
684	        // customerCode today; the memberId once the two are unified), with a monotonic sequence.
685	        AUDIT.info(new OwnerCreatedEvent(CREATE_SEQUENCE.incrementAndGet(), owner.getId(),
686	            owner.getCustomerCode(), membershipLevel).toJson());
687	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
688	        ownerDto.setMembershipLevel(membershipLevel);
689	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
690	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
691	        headers.setLocation(UriComponentsBuilder.newInstance()
692	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
693	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
694	    }
