757	        this.clinicService.savePet(pet);
758	        PetDto petDto = petMapper.toPetDto(pet);
759	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
760	            .buildAndExpand(pet.getId()).toUri());
